#!/bin/bash
# Package M4 differential oracle: builds tests/oracle/net_settings_oracle.cpp against the
# reference build's libkicommon.so (real NET_SETTINGS / NETCLASS code), runs it on
# tests/data/net_settings/scenarios.txt (hand-written) and corpus_scenarios.txt (generated by
# tests/oracle/net_settings_corpus.py from every corpus .kicad_pro with netclass patterns) and
# writes tests/golden/net_settings.txt / net_settings_corpus.txt, replayed by the Rust tests
# `net_settings::tests::oracle_scenarios` / `oracle_corpus_scenarios`.
#
# Usage: tests/oracle/net_settings_golden.sh   (run from anywhere)
set -euo pipefail
here=$(cd "$(dirname "$0")/.." && pwd)
root=$(cd "$here/../../.." && pwd)
build=${ORACLE_BUILD:-/home/user/kicad-oracle/build}
obj=${OBJ_DIR:-/home/user/kicad-oracle/build-net-settings-oracle}
mkdir -p "$obj"

# Compile flags of common/project/net_settings.cpp (kicommon), without the PCH and outputs.
python3 - "$build" "$obj/cflags.txt" <<'PY'
import json, shlex, sys
build, out = sys.argv[1], sys.argv[2]
for e in json.load(open(build + "/compile_commands.json")):
    if e["file"].endswith("common/project/net_settings.cpp"):
        args = shlex.split(e["command"])[1:]
        keep, skip = [], False
        for a in args:
            if skip: skip = False; continue
            if a in ("-o", "-c", "-include", "-x"): skip = True; continue
            if a.endswith(".cpp") or a.startswith("-Winvalid-pch") or a.startswith("-fvisibility"):
                continue
            if a == "-Dkicommon_EXPORTS": continue
            keep.append(a)
        open(out, "w").write(" ".join(shlex.quote(a) for a in keep))
        break
else:
    sys.exit("net_settings.cpp not found in compile_commands.json")
PY
eval "CFLAGS=( $(cat "$obj/cflags.txt") )"
nice -n 15 c++ "${CFLAGS[@]}" -Wno-shadow "$here/oracle/net_settings_oracle.cpp" -o "$obj/net_settings_oracle" \
    -L"$build/common" -lkicommon -Wl,-rpath,"$build/common" $(wx-config --libs base,core)

"$obj/net_settings_oracle" "$here/data/net_settings/scenarios.txt" > "$here/golden/net_settings.txt"
"$obj/net_settings_oracle" "$here/data/net_settings/corpus_scenarios.txt" > "$here/golden/net_settings_corpus.txt"
wc -l "$here/golden/net_settings.txt" "$here/golden/net_settings_corpus.txt"
